import { mutex } from "./lib/core.mjs";
import { isMain } from "./lib/core.mjs";
import fs from "node:fs";
import path from "node:path";
import { load, read, json, hash, artifactPath, main } from "./lib/core.mjs";
import { terminationProof } from "./lib/recovery.mjs";
import { streamRunId } from "./lib/runtime.mjs";
export function importTermination(o) {
  return mutex(o.target, () => importTerminationUnlocked(o));
}
function importTerminationUnlocked(o) {
  const c = load(o.target),
    s = read(path.join(c.dir, "current-task.json")),
    raw = fs.readFileSync(o.raw),
    es = raw
      .toString()
      .split("\n")
      .filter((x) => x.trim())
      .map(JSON.parse);
  const launches = es.filter(
    (e) =>
      e.type === "user" &&
      e.message?.content?.some(
        (b) => b.type === "tool_result" && b.tool_use_id === o.tool_use,
      ) &&
      e.tool_use_result?.taskId,
  );
  if (launches.length !== 1)
    throw Error("Missing/ambiguous actual Workflow launch result");
  const launch = launches[0],
    r = {
      ...launch.tool_use_result,
      runId: streamRunId(es, {
        session_id: launch.session_id,
        tool_use_id: o.tool_use,
        task_id: launch.tool_use_result.taskId,
        launch_run_id: launch.tool_use_result.runId,
      }),
    },
    terminal = es
      .filter(
        (e) =>
          e.type === "system" &&
          e.subtype === "task_notification" &&
          e.session_id === launch.session_id &&
          e.task_id === r.taskId &&
          e.run_id === r.runId,
      )
      .at(-1);
  if (!terminal) throw Error("Workflow terminal notification missing");
  const record = "sdk-termination-" + hash(raw) + ".jsonl";
  fs.writeFileSync(artifactPath(c.dir, record), raw);
  const p = {
      version: 2,
      source:
        o.mode === "TEST_FIXTURE"
          ? "TEST_FIXTURE"
          : "parent-runtime-observation",
      run_id: s.run_id,
      task_id: s.task_id,
      attempt_id: s.attempt_id,
      state: terminal.status,
      observed_at: new Date().toISOString(),
      record,
      sha256: hash(raw),
      sdk_session_id: launch.session_id,
      sdk_task_id: r.taskId,
      sdk_run_id: r.runId,
      sdk_tool_use_id: o.tool_use,
    },
    file = path.join(c.dir, "termination-import.json");
  json(file, p);
  terminationProof(c.dir, file, s, { fixture: o.mode === "TEST_FIXTURE" });
  return { status: "TERMINATION_OBSERVED", file };
}
if (isMain(import.meta.url))
  main((o) => console.log(JSON.stringify(importTermination(o), null, 2)));

import { mutex } from "./lib/core.mjs";
import { isMain } from "./lib/core.mjs";
import fs from "node:fs";
import path from "node:path";
import {
  observationContext,
  read,
  json,
  hash,
  context,
  artifactPath,
  main,
} from "./lib/core.mjs";
import {
  runtimeObservation,
  invocationWindow,
  routingProvenance,
  streamRunId,
} from "./lib/runtime.mjs";
import { invocationTag } from "./lib/core.mjs";
export function importRuntime(o) {
  return mutex(o.target, () => importRuntimeUnlocked(o));
}
function importRuntimeUnlocked(o) {
  const c = observationContext(o.target),
    s = read(path.join(c.dir, "current-task.json")),
    task = c.backlog.items.find((t) => t.id === o.task),
    ctx =
      o.task === "mission"
        ? {
            run_id: s.run_id,
            task_id: s.task_id,
            attempt_id: s.attempt_id,
            session_id: c.session.session_id,
          }
        : context(c, task);
  const raw = fs.readFileSync(o.raw),
    events = raw
      .toString()
      .split("\n")
      .filter((x) => x.trim())
      .map(JSON.parse),
    starts = events.filter(
      (e) =>
        e.type === "system" &&
        e.subtype === "task_started" &&
        e.tool_use_id === o.tool_use,
    );
  if (starts.length !== 1)
    throw Error("Specify a uniquely observed SDK tool_use_id");
  const start = starts[0],
    window = invocationWindow(events, {
      sdk_task_id: start.task_id,
      sdk_run_id: start.run_id,
      tool_use_id: o.tool_use,
      sdk_session_id: start.session_id,
    }),
    // Forwarded subagent messages (Agent tool) or, for native Workflows, the
    // runtime's own workflow_agent progress record carrying this stage's tag.
    msg =
      window.messages.filter((e) => e.message?.model).at(-1) ||
      window.agents
        .filter((a) => a.label === invocationTag(c, ctx, o.stage) && a.message.model)
        .at(-1);
  if (!msg)
    throw Error(
      "Subagent evidence absent: no forwarded subagent messages and no workflow_agent progress carrying this stage tag (use --forward-subagent-text)",
    );
  const digest = hash(raw),
    record = "sdk-" + digest + ".jsonl",
    name =
      "runtime-" +
      hash(JSON.stringify({ ...ctx, stage: o.stage, tool_use: o.tool_use })) +
      ".json";
  fs.writeFileSync(artifactPath(c.dir, record), raw);
  const r = {
    version: 2,
    mode: o.mode === "TEST_FIXTURE" ? "TEST_FIXTURE" : "LIVE",
    source: "claude-sdk-jsonl",
    ...ctx,
    stage: o.stage,
    expected_model: o.expected,
    record,
    sha256: digest,
    sdk_session_id: start.session_id,
    tool_use_id: o.tool_use,
    message_uuid: msg.uuid,
    ...(msg.agent_type
      ? {
          evidence_kind: "workflow-agent-progress",
          agent_type: msg.agent_type,
          agent_id: msg.agent_id,
        }
      : {}),
    sdk_task_id: start.task_id,
    sdk_run_id: start.run_id,
    observed_at: new Date().toISOString(),
    provenance: routingProvenance(
      c,
      ctx,
      events.find(
        (e) =>
          e.type === "system" &&
          e.subtype === "init" &&
          e.session_id === start.session_id,
      )?.cwd,
    ),
  };
  json(artifactPath(c.dir, name), r);
  const observation = runtimeObservation(
      c,
      name,
      {},
      { fixture: o.mode === "TEST_FIXTURE" },
    ),
    p = path.join(c.dir, "routing.json"),
    routing = fs.existsSync(p) ? read(p) : [];
  if (!Array.isArray(routing))
    throw Error("Legacy/invalid routing manifest; migrate first");
  if (!routing.includes(name)) routing.push(name);
  json(p, routing);
  return {
    status: observation.mode === "LIVE" ? "OBSERVED" : "TEST_FIXTURE_OBSERVED",
    name,
    observation,
  };
}
if (isMain(import.meta.url))
  main((o) => console.log(JSON.stringify(importRuntime(o), null, 2)));

