1	import fs from "node:fs";
2	import path from "node:path";
3	import { shared, hash, json, main, isMain, load } from "./lib/core.mjs";
4	import { roles } from "./install-agents.mjs";
5	
6	// Observed live (Claude Code 2.1.310): for every native Workflow agent the runtime
7	// writes agent-ID.meta.json (agentType, model, tagged description) and
8	// agent-ID.prefix.json (state.toolNames = the tool list actually sent to the
9	// model) under the launch result's transcriptDir. That is a runtime record, not a
10	// model self-report, so it can back the "reviewer/auditor are read-only" check.
11	const READ = new Set(["Read", "Grep", "Glob"]);
12	const ALLOWED_EXTRA = new Set(["StructuredOutput"]);
13	const FORBIDDEN = [
14	  "Write", "Edit", "Bash", "NotebookEdit", "Agent", "Task", "Workflow",
15	  "SendMessage", "TaskCreate", "WebFetch", "Skill",
16	];
17	const frontTools = (role) => {
18	  const m = fs
19	    .readFileSync(path.join(shared, "agents", role + ".md"), "utf8")
20	    .match(/^tools:\s*(.+)$/m);
21	  return m ? m[1].split(",").map((x) => x.trim()) : [];
22	};
23	export function readonlyEvidence(o) {
24	  const c = load(o.target),
25	    events = fs
26	      .readFileSync(o.raw, "utf8")
27	      .split("\n")
28	      .filter((x) => x.trim())
29	      .map(JSON.parse),
30	    launches = events.filter(
31	      (e) =>
32	        e.type === "user" &&
33	        e.message?.content?.some?.(
34	          (b) => b.type === "tool_result" && b.tool_use_id === o.tool_use,
35	        ) &&
36	        e.tool_use_result?.transcriptDir,
37	    );
38	  if (launches.length !== 1)
39	    throw Error("Specify a uniquely observed Workflow launch with transcriptDir");
40	  const dir = launches[0].tool_use_result.transcriptDir;
41	  if (!fs.existsSync(dir))
42	    return { status: "UNVERIFIED", reason: "Runtime transcriptDir is no longer present: " + dir };
43	  const agents = [];
44	  for (const f of fs.readdirSync(dir).filter((n) => n.endsWith(".meta.json"))) {
45	    const id = f.replace(/^agent-/, "").replace(/\.meta\.json$/, ""),
46	      metaPath = path.join(dir, f),
47	      prefixPath = path.join(dir, "agent-" + id + ".prefix.json");
48	    if (!fs.existsSync(prefixPath)) continue;
49	    const meta = JSON.parse(fs.readFileSync(metaPath, "utf8")),
50	      prefix = JSON.parse(fs.readFileSync(prefixPath, "utf8")),
51	      role = roles.find((r) => (meta.agentType || "").endsWith(r)),
52	      tools = prefix.state?.toolNames;
53	    if (!role || !Array.isArray(tools)) continue;
54	    const declared = frontTools(role),
55	      readonlyRole = declared.every((t) => READ.has(t)),
56	      extra = tools.filter((t) => !READ.has(t) && !ALLOWED_EXTRA.has(t)),
57	      violation = tools.filter((t) => FORBIDDEN.includes(t));
58	    agents.push({
59	      agent_id: id,
60	      agent_type: meta.agentType,
61	      role,
62	      model: meta.model,
63	      description: meta.description,
64	      declared_tools: declared,
65	      runtime_tool_names: tools,
66	      expected_readonly: readonlyRole,
67	      readonly_ok: readonlyRole ? violation.length === 0 && extra.length === 0 : null,
68	      meta_sha256: hash(fs.readFileSync(metaPath)),
69	      prefix_sha256: hash(fs.readFileSync(prefixPath)),
70	      meta,
71	      prefix_state: prefix.state && { toolNames: tools, model: prefix.state.model },
72	    });
73	  }
74	  const ro = agents.filter((a) => a.expected_readonly),
75	    bad = ro.filter((a) => !a.readonly_ok),
76	    writers = agents.filter((a) => !a.expected_readonly);
77	  const sentinel = o.sentinel && fs.existsSync(o.sentinel);
78	  const status = bad.length || sentinel
79	      ? "FAIL"
80	      : ro.length
81	        ? "READONLY_OBSERVED"
82	        : "UNVERIFIED",
83	    out = {
84	      version: 1,
85	      status,
86	      reason:
87	        status === "UNVERIFIED"
88	          ? "No read-only role (reviewer/auditor) agent was run in this Workflow"
89	          : status === "FAIL"
90	            ? "A read-only role received a write/delegation tool or the sentinel exists"
91	            : "Runtime-recorded tool lists for read-only roles contain only Read/Grep/Glob (+StructuredOutput); writer roles differ",
92	      contrast_writers_have_write: writers.some((a) => a.runtime_tool_names.includes("Write")),
93	      sentinel_absent: o.sentinel ? !sentinel : null,
94	      transcript_dir: dir,
95	      agents,
96	      observed_at: new Date().toISOString(),
97	    };
98	  const file = path.join(c.dir, "evidence", "readonly-" + hash(JSON.stringify(agents)).slice(0, 16) + ".json");
